[CmdletBinding()]
param([string]$OutputPath='ES/Output/WebPageStudio/cache-policy-v1.json',[string]$PolicyId='web-cache-policy-v1')
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\';$schema=Join-Path $root 'ES/Automation/Contracts/es-web-cache-policy-v1.schema.json';$hash=(Get-FileHash $schema -Algorithm SHA256).Hash.ToLowerInvariant()
$o=[ordered]@{schemaVersion=1;recordType='WebPageStudioCachePolicy';policyId=$PolicyId;routes=@([ordered]@{routeId='home';renderPolicy='prerender';cacheControl=[ordered]@{maxAgeSeconds=86400;staleWhileRevalidateSeconds=3600;staleIfErrorSeconds=86400;private=$false};keyStrategy='immutable-hash';invalidationTags=@('webpage.home','content.default');fallback='last-known-good'},[ordered]@{routeId='data/dashboard';renderPolicy='cached';cacheControl=[ordered]@{maxAgeSeconds=60;staleWhileRevalidateSeconds=300;staleIfErrorSeconds=900;private=$false};keyStrategy='etag-version';invalidationTags=@('dashboard.data');fallback='shell-only'});invalidation=[ordered]@{mode='tagged';versionSource='content-manifest-sha256';onMutation='mark-stale';recovery='serve-stale'};evidence=[ordered]@{status='designed';runtimeStatus='runtime-not-run';sourceHash=$hash};nonClaims=@('No network request or production CDN cache was executed','Cache policy does not authorize mutation or deployment')};$out=Join-Path $root $OutputPath;if(Test-Path $out){throw "Refusing to overwrite existing cache policy: $out"};New-Item -ItemType Directory (Split-Path $out) -Force|Out-Null;[IO.File]::WriteAllText($out,($o|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false));$o|ConvertTo-Json -Depth 12
